        'H:chkAdvertisingID' = "Retire l'identifiant que les applications utilisent pour vous montrer des publicités ciblées."
        'H:chkTailoredExp' = "Microsoft n'utilise plus vos données pour des conseils et publicités personnalisés."
        'H:chkFeedback' = "Plus de fenêtres qui demandent votre avis sur Windows."
        'H:chkErrorReporting' = "Les erreurs des programmes ne sont plus envoyées à Microsoft. Moins d'activité après un plantage."
        'H:chkInkingTyping' = "Windows n'apprend plus de ce que vous écrivez et tapez. Plus de confidentialité."
