        'H:chkVBS' = "Wyłącza zabezpieczenia oparte na wirtualizacji. Więcej klatek w grach, ale słabsza ochrona przed złośliwym oprogramowaniem."
        'H:chkMitigations' = "Usuwa część zabezpieczeń przed exploitami. Zysk wydajności, ale system jest bardziej narażony."
