        'H:chkActivityHistory' = "Windows przestaje zapisywać, co i kiedy otwierasz. Więcej prywatności."
        'H:chkLocationTracking' = "Wyłącza lokalizację urządzenia. Aplikacje nie wiedzą, gdzie jesteś."
