        'H:chkFeedback' = "Koniec z oknami, które pytają o opinię na temat Windows."
        'H:chkErrorReporting' = "Błędy programów nie są już wysyłane do Microsoft. Mniej aktywności po awarii."
        'H:chkInkingTyping' = "Windows przestaje uczyć się z tego, co piszesz i wpisujesz. Więcej prywatności."
        'H:chkWiFiSense' = "Blokuje automatyczne udostępnianie sieci Wi-Fi i łączenie z nieznanymi hotspotami."
        'H:chkConsumerFeatures' = "Nie pozwala Windows samodzielnie instalować promocyjnych aplikacji i gier."
        'H:chkStoreSearch' = "Usuwa sugestie z internetu i Sklepu z wyszukiwania. Czystsze i szybsze wyniki."
        'H:chkSuggestedContent' = "Bez porad i promocji w Ustawieniach i w systemie."
        'H:chkLockScreenAds' = "Usuwa zmieniające się obrazy, porady i reklamy z ekranu blokady."
        'H:chkStartBing' = "Wyszukiwanie w menu Start szuka tylko na komputerze, nie w internecie. Szybciej i bardziej prywatnie."
        'H:chkStartRecs' = "Usuwa sugestie aplikacji i plików z menu Start."
        'H:chkStartTracking' = "Windows przestaje prowadzić listę najczęściej używanych aplikacji i ostatnich dokumentów."
        'H:chkFolderDiscovery' = "Eksplorator przestaje zgadywać typ każdego folderu. Duże foldery otwierają się szybciej."
        'H:chkWindowsAI' = "Wyłącza Copilot, Recall i funkcje AI w Windows. Mniejsze zużycie zasobów i więcej prywatności."
        'H:chkEdgeDebloat' = "Edge nie działa już w tle i nie ładuje stron z wyprzedzeniem. Mniej zajętej pamięci."
        'H:chkOneDriveRemove' = "Zatrzymuje synchronizację OneDrive. Przydatne, jeśli nie korzystasz z chmury Microsoft."
        'H:chkOutlookNew' = "Blokuje automatyczne przejście na nowy Outlook. Zostajesz przy wersji, której używasz."
        'H:chkServicesManual' = "Rzadko używane usługi startują tylko wtedy, gdy są potrzebne. Lżejszy start."
        'H:chkDeliveryOpt' = "Komputer przestaje udostępniać aktualizacje innym komputerom w internecie. Oszczędzasz łącze."
        'H:chkBitLocker' = "Zapobiega automatycznemu szyfrowaniu dysku. Nieco szybszy dysk i brak klucza odzyskiwania do przechowywania."
        'H:chkWPBT' = "Nie pozwala oprogramowaniu producenta instalować programów w Windows bez twojej wiedzy."
        'H:chkBackgroundApps' = "Aplikacje ze Sklepu nie działają po zamknięciu. Mniejsze zużycie baterii i pamięci."
        'H:chkTeredo' = "Wyłącza stary, prawie nieużywany tunel sieciowy. Może poprawić połączenie w grach online."
        'H:chkRDPWarnings' = "Bez powtarzanych ostrzeżeń przy otwieraniu znanych połączeń Pulpitu zdalnego."
        'H:chkRemoteAssistance' = "Nie pozwala innym prosić o przejęcie kontroli nad twoim komputerem. Więcej bezpieczeństwa."
        'H:chkCompanionApps' = "Windows nie pobiera już aplikacji towarzyszących po podłączeniu urządzenia."
        'H:chkDriverUpdates' = "Windows Update nie zastępuje już sterowników zainstalowanych przez ciebie."
        'H:chkDarkTheme' = "Przełącza Windows i aplikacje na ciemny motyw. Mniej męczy oczy."
        'H:chkFileExt' = "Pokazuje .exe, .pdf i inne rozszerzenia. Od razu rozpoznasz podejrzane pliki."
        'H:chkHiddenFiles' = "Pokazuje ukryte pliki i foldery w Eksploratorze."
        'H:chkLongPaths' = "Pozwala na bardzo długie ścieżki plików. Unika błędów przy głęboko zagnieżdżonych projektach i archiwach."
        'H:chkClassicMenu' = "Przywraca pełne menu prawego przycisku, bez przechodzenia przez «Pokaż więcej opcji»."
        'H:chkExplorerThisPC' = "Eksplorator otwiera się na Ten komputer, z dyskami i folderami na widoku."
        'H:chkRemove3D' = "Usuwa folder Obiekty 3D, z którego prawie nikt nie korzysta."
        'H:chkRecycleConfirm' = "Pyta przed przeniesieniem pliku do Kosza. Mniej przypadkowych usunięć."
        'H:chkMenuDelay' = "Menu otwierają się natychmiast, bez małego domyślnego opóźnienia."
        'H:chkStartMorePins' = "W menu Start więcej miejsca na przypięte aplikacje, mniej na porady."
        'H:chkStartHideRec' = "Ukrywa sekcję Polecane w menu Start. Czystszy Start."
        'H:chkStartNoWeb' = "Usuwa sugerowane witryny z menu Start."
        'H:chkStartNoAccount' = "Bez komunikatów o koncie Microsoft w menu Start."
        'H:chkTaskbarCenter' = "Utrzymuje ikony paska zadań na środku, jak w Windows 11."
        'H:chkTaskbarSearch' = "Usuwa pole wyszukiwania z paska. Wyszukiwanie nadal działa po naciśnięciu klawisza Windows."
        'H:chkTaskbarTaskView' = "Usuwa przycisk Widok zadań z paska."
        'H:chkTaskbarWidgets' = "Usuwa widżety i wiadomości z paska. Mniej pamięci i mniej rozpraszaczy."
        'H:chkTaskbarChat' = "Usuwa ikonę Czatu i Teams z paska."
        'H:chkTaskbarEndTask' = "Dodaje «Zakończ zadanie» do prawego przycisku na pasku. Zamkniesz zawieszony program bez Menedżera zadań."
        'H:chkBatteryPct' = "Pokazuje procent naładowania obok ikony baterii."
        'H:chkSettingsHome' = "Ustawienia otwierają się od razu na przydatnych sekcjach, bez promocyjnej strony głównej."
        'H:chkWindowSnapping' = "Włącza przyciąganie okien po przeciągnięciu ich do krawędzi ekranu."
        'H:chkMouseAccel' = "Wskaźnik zawsze przesuwa się o tę samą odległość. Precyzyjniejsze i powtarzalne celowanie w grach."
        'H:chkNumLock' = "Klawiatura numeryczna jest aktywna od razu po włączeniu komputera."
        'H:chkStickyKeys' = "Bez okna Klawiszy trwałych po kilkukrotnym naciśnięciu Shift, także w grach."
        'H:chkScrollbars' = "Paski przewijania są zawsze widoczne, zamiast pojawiać się po najechaniu."
        'H:chkLockScreen' = "Pomija ekran blokady i od razu przechodzi do logowania."
        'H:chkLogonBlur' = "Usuwa rozmycie tła logowania. Ostrzejszy obraz i nieco szybsze logowanie."
        'H:chkBSODVerbose' = "Niebieski ekran pokazuje szczegóły błędu. Łatwiej ustalić przyczynę awarii."
        'H:chkLogonVerbose' = "Przy starcie i zamykaniu widzisz, co robi Windows. Pomaga znaleźć, co go spowalnia."
        'H:chkApplyNetwork' = "Stosuje ustawienia ze strony Sieć. Bez tego pola strona jest tylko informacyjna."
        'H:chkApplyDns' = "Używa serwerów DNS wybranych w menu. Strony otwierają się szybciej, a z niektórymi usługami jest mniej reklam."
        'H:chkNetPowerSave' = "Karta sieciowa nie przechodzi w oszczędzanie energii. Stabilniejsze połączenie i równiejszy ping."
        'H:chkDisableIPv6' = "Wyłącza IPv6. Przydatne tylko, jeśli dostawca go nie używa, a masz problemy z połączeniem."
        'H:chkStorageProfile' = "Stosuje optymalizacje przygotowane dla wybranego typu dysku: SSD lub HDD."
