        'H:chkApplyDns' = "Usa os servidores DNS escolhidos no menu. Páginas abrem mais rápido e, com alguns serviços, há menos anúncios."
        'H:chkNetPowerSave' = "A placa de rede não entra mais em economia de energia. Conexão mais estável e ping mais regular."
        'H:chkDisableIPv6' = "Desliga o IPv6. Útil só se o seu provedor não o usa e você tem problemas de conexão."
        'H:chkStorageProfile' = "Aplica as otimizações pensadas para o tipo de disco escolhido: SSD ou disco mecânico."
        'H:chkDiskCleanup' = "Exclui arquivos de sistema desnecessários e versões antigas de atualizações. Recupera espaço, às vezes vários GB."
        'H:chkTempCleanup' = "Esvazia as pastas de arquivos temporários. Mais espaço livre."
        'H:chkSmartChkdsk' = "Verifica o disco no próximo reinício do jeito certo para SSD ou disco mecânico. Corrige erros do sistema de arquivos."
        'H:chkStorageSense' = "O Windows para de apagar arquivos sozinho para abrir espaço. Você decide o que remover."
        'H:chkReservedStorage' = "Libera o espaço que o Windows reserva para atualizações, cerca de 7 GB."
        'H:chkFastStartup' = "Todo desligamento vira um desligamento completo. Resolve problemas de drivers e dual boot."
        'H:chkHibernation' = "Desliga a hibernação e libera em C: um espaço próximo de boa parte da RAM."
        'H:chkS0Sleep' = "Em suspensão o PC não fica conectado à internet. Consome menos e não acorda sozinho."
        'H:chkS3Sleep' = "Usa a suspensão clássica no lugar da moderna. O notebook não esquenta na mochila."
        'H:chkGpuTdr' = "Dá mais tempo à placa de vídeo antes que o Windows a reinicie. Menos telas pretas sob carga pesada."
        'H:chkGpuMsi' = "Muda o modo como a placa de vídeo sinaliza o processador. Pode reduzir a latência."
        'H:chkNvTelemetry' = "Para o envio de dados de uso para a NVIDIA. Menos processos em segundo plano."
        'H:chkNvGfe' = "O GeForce Experience não inicia mais sozinho. Inicialização mais leve."
        'H:chkNvPerfMode' = "Mantém a placa NVIDIA na frequência máxima. Desempenho constante, consumo maior."
        'H:chkNvUpdates' = "O driver da NVIDIA para de procurar atualizações sozinho."
        'H:chkAmdUx' = "Para o envio de dados de uso para a AMD."
        'H:chkAmdBloat' = "Impede que os programas extras da AMD iniciem com o Windows. Inicialização mais leve."
        'H:chkIntelBloat' = "Os serviços extras da placa Intel só iniciam quando necessários."
        'H:chkSvcSysMain' = "O Windows para de pré-carregar na memória os apps que você usa com frequência. Útil em SSDs rápidos, onde não é necessário."
        'H:chkSvcDiag' = "Para os serviços que analisam problemas e desempenho em segundo plano."
        'H:chkSvcErrors' = "Para o serviço que coleta e envia relatórios de erro."
        'H:chkSvcPca' = "Para o serviço que verifica a compatibilidade de programas antigos."
        'H:chkSvcDiscovery' = "O PC para de procurar dispositivos na rede local. Menos tráfego, mas impressoras e TVs de rede podem não aparecer."
        'H:chkSvcSensors' = "Para os serviços de sensores e localização. Útil em desktops, que não os têm."
        'H:chkSvcSmartCard' = "Para os serviços de cartões inteligentes. Não são necessários se você não usa leitores de cartão."
        'H:chkSvcParental' = "Para o controle dos pais e o programa Insider. Não são necessários num PC pessoal."
        'H:chkSvcHyperV' = "Para os serviços de máquinas virtuais. Mantenha-os se usa Hyper-V, WSL ou o emulador Android."
        'H:chkSvcPrint' = "Para o serviço de impressão. Só se você nunca imprime deste PC."
        'H:chkSvcSearch' = "Para a indexação de arquivos. Menos trabalho do disco, mas a pesquisa fica lenta."
        'H:chkSvcRemote' = "Para a Área de Trabalho Remota e o acesso remoto ao registro. Mais segurança se você nunca acessa de fora."
        'H:chkSvcBiometric' = "Para a digital e o reconhecimento facial. Evite se entra com o Windows Hello."
        'H:chkSvcTouch' = "Para a caneta e o teclado virtual. Evite em tablets e notebooks touch."
        'H:chkTaskExtra' = "Desliga cerca de vinte tarefas automáticas da Microsoft que não são necessárias. Menos trabalho escondido."
        'H:chkTaskMaint' = "O Windows não roda mais a manutenção automática de madrugada. O PC não acorda nem fica lento de surpresa."
        'H:chkTaskDefrag' = "Para a otimização automática das unidades. Em SSD, ela deve ser feita à mão pela página Armazenamento."
        'H:chkPrefetch' = "O Windows para de preparar com antecedência os arquivos dos programas. Menos gravações no SSD."
        'H:chkFth' = "O Windows para de aplicar correções automáticas aos programas que travam. Comportamento mais previsível."
        'H:chkAppCompat' = "Desliga as verificações de compatibilidade dos programas. Os programas abrem um pouco mais rápido."
        'H:chkSvcHostSplit' = "Agrupa os serviços do Windows em menos processos. Menos memória usada e um Gerenciador de Tarefas mais legível."
        'H:chkMemCompression' = "O Windows para de comprimir a memória. Menos trabalho do processador, mas é preciso bastante RAM."
        'H:chkWuNoReboot' = "As atualizações não reiniciam mais o PC enquanto você o usa."
        'H:chkWuDefer' = "As novas versões do Windows chegam um ano depois, já estáveis. As correções de segurança continuam chegando."
        'H:chkWuNoStore' = "Os apps da Store param de se atualizar sozinhos em segundo plano."
        'H:chkBootQuiet' = "Inicia sem o logotipo animado. Tela mais limpa e inicialização um pouco mais rápida."
        'H:chkBootMenu' = "Traz de volta o menu de inicialização clássico, que permite entrar no modo de segurança com F8."
        'H:chkBootTimeout' = "Se houver vários sistemas instalados, o PC inicia na hora sem esperar no menu de escolha."
        'H:chkBootDynTick' = "O processador mantém um ritmo de sistema constante. Em alguns PCs reduz a latência, em outros não: teste."
        'H:chkBootTsc' = "Deixa mais precisa a medição do tempo entre os núcleos do processador. Pode melhorar a fluidez: teste."
        'H:chkAppxBloat' = "Remove apps pré-instalados como notícias, clima, mapas e Skype. Mais espaço e um Iniciar mais organizado."
